  git(['add', '-A']);
  git(
    ['commit', '-q', '-m', 'seed'],
    env: {
      'GIT_COMMITTER_DATE':
          (DateTime.now()
                      .subtract(Duration(hours: tagAgeHours))
                      .millisecondsSinceEpoch ~/
                  1000)
              .toString(),
    },
  );
  git(
    ['tag', '-a', 'v0.1.495', '-m', 'Release v0.1.495'],
    env: {
      'GIT_COMMITTER_DATE':
