    ...Directory('.github/workflows')
        .listSync()
        .whereType<File>()
        .where((f) => f.path.endsWith('.yml') || f.path.endsWith('.yaml'))
        .map((f) => f.path),
    ...Directory('.github/actions')
        .listSync(recursive: true)
        .whereType<File>()
        .where(
          (f) =>
              f.path.endsWith('action.yml') || f.path.endsWith('action.yaml'),
        )
        .map((f) => f.path),
