        r.originHeadBefore,
        reason: 'no release may land inside the coalesce window',
      );
      expect(
        r.originTags(),
        ['v0.1.495'],
        reason: 'the guard must not cut v0.1.496',
      );
      expect(r.ghLog(), isEmpty);
    },
  );

