    'FA_REAL_GIT': realGit,
    'FA_RACER': racer,
    'FA_RACE_FILE': raceFile,
    'FA_GH_LOG': ghLogPath,
    'GITHUB_REPOSITORY': 'OWNER/REPO',
    'GH_TOKEN': 'stub',
