/// flutter / file-mutation shims: the tag-only script mutates ZERO files —
/// the git tag is the single source of truth.
AutoReleaseRun runAutoReleaseDirect(
  String name, {
  int tagAgeHours = 3,
  bool dryRun = false,
  String raceMode = 'never',
