  File('$bin/gh').writeAsStringSync('''
#!/usr/bin/env bash
echo "\$*" >> "\$FA_GH_LOG"
exit 0
''');
  Process.runSync('chmod', ['+x', '$bin/gh']);

  final realGit = _resolveRealGit(bin);
