+      expect(
+        nightly.contains(
+          'stage_publish_package.sh /tmp/publish-stage "\$next"',
+        ),
+        isTrue,
+        reason:
+            'the nightly publish dry-run must validate the STAMPED staged '
+            'tree (gh-1522 risk note: the dry-run now also validates the '
+            'stamp, not only the payload)',
