4:+++ b/test/publish_staging_test.dart
9:+
10:+  // ── gh-1522 rework (PR #1526 thread) — the stamper, exercised ────────────
11:+  // The string assertions above pin the WIRING; this group runs the real
12:+  // script against a fixture stage and asserts the staged BYTES — a bad
13:+  // stamp ships 0.0.0-dev or a malformed changelog to pub.dev. The fixture
14:+  // repo dir doubles as the CWD: release_notes.sh reads CHANGELOG.md from
15:+  // the CWD, exactly like the publish job running at the repo root.
16:+  group('gh-1522 rework — stamp_staged_release.sh behavior', () {
17:+    final tmp = Directory.systemTemp.createTempSync('stamp-fixture-');
18:+
19:+    /// A fixture "repo" (CWD for the run) plus a staged tree inside it.
20:+    _StampFixture fixture({String? repoChangelog, String? stagedChangelog}) {
21:+      final dir = Directory(
22:+        '${tmp.path}/fx-${tmp.listSync().length}',
23:+      )..createSync(recursive: true);
24:+      final repo = '${dir.path}/repo';
25:+      final stage = '${dir.path}/stage';
26:+      Directory(repo).createSync();
27:+      Directory(stage).createSync();
28:+      File('$repo/CHANGELOG.md').writeAsStringSync(
29:+        repoChangelog ??
30:+            '# Changelog\n\nCurated window.\n\n## Unreleased\n\n'
31:+                '- pending bullet\n\n## 1.0.998\n\n- old entry\n',
32:+      );
33:+      File('$stage/pubspec.yaml').writeAsStringSync(
34:+        'name: fa\nversion: 0.0.0-dev\n',
35:+      );
36:+      File('$stage/CHANGELOG.md').writeAsStringSync(
37:+        stagedChangelog ?? File('$repo/CHANGELOG.md').readAsStringSync(),
38:+      );
39:+      return _StampFixture(repo: repo, stage: stage);
40:+    }
41:+
42:+    ProcessResult stamp(_StampFixture fx, String version) => Process.runSync(
43:+      'bash',
44:+      [
45:+        File('scripts/stamp_staged_release.sh').absolute.path,
46:+        fx.stage,
47:+        version,
