25:+      final stage = '${dir.path}/stage';
26:+      Directory(repo).createSync();
27:+      Directory(stage).createSync();
28:+      File('$repo/CHANGELOG.md').writeAsStringSync(
29:+        repoChangelog ??
30:+            '# Changelog\n\nCurated window.\n\n## Unreleased\n\n'
31:+                '- pending bullet\n\n## 1.0.998\n\n- old entry\n',
32:+      );
33:+      File('$stage/pubspec.yaml').writeAsStringSync(
34:+        'name: fa\nversion: 0.0.0-dev\n',
35:+      );
36:+      File('$stage/CHANGELOG.md').writeAsStringSync(
37:+        stagedChangelog ?? File('$repo/CHANGELOG.md').readAsStringSync(),
38:+      );
39:+      return _StampFixture(repo: repo, stage: stage);
40:+    }
41:+
42:+    ProcessResult stamp(_StampFixture fx, String version) => Process.runSync(
43:+      'bash',
44:+      [
45:+        File('scripts/stamp_staged_release.sh').absolute.path,
46:+        fx.stage,
47:+        version,
48:+      ],
49:+      workingDirectory: fx.repo,
50:+    );
51:+
52:+    test('stamps the pubspec to exactly the tag version', () {
53:+      final fx = fixture();
54:+      final r = stamp(fx, '1.0.999');
55:+      expect(r.exitCode, 0, reason: '${r.stdout}${r.stderr}');
